std::string markdownToHtml(const std::string& markdown) {
    std::stringstream html;
    std::string line, match;
    std::regex regex(R"(.*?)#");
    while (std::getline(markdown, line)) {
        if (std::regex_search(line, match, regex)) {
            html << "<h1>" << match[1] << "</h1>\n";
        } else {
            html << line << "\n";
        }
    }
    return html.str();
}

int main() {
    std::string markdown = "# Example Title\nThis is a paragraph.\nAnother line.\nAnother line.";
    std::string html = markdownToHtml(markdown);
    std::cout << html << std::endl;
    return 0;
}
